/* @socom-skeleton body StopRumbler__9CSealCtrlFv */
void CSealCtrl::StopRumbler()
{
    CPad* pad;
    
    if (m_padid < 2)
    {
        pad = CInput::m_pads[m_padid];
    }
    else
    {
        pad = NULL;
    }

    if (pad)
    {
        pad->m_ActData[1] = 0; /* 0x284294: both actuator bytes (+0xd, +0xc) */
        pad->m_ActData[0] = 0;
    }

    m_highrumbletime = 0.0f;
    m_rumbletime = 0.0f;
    m_rumblestr = 0.0f;

    CInput::Flush();
    CZSealBody::StopAllHeartbeatSounds();
}

/* @socom-skeleton stub TickRumbler__9CSealCtrlFf */
void CSealCtrl::TickRumbler(float dT)
{
	/* 0x284180: the controller pad's actuators: the small motor at the rumble strength while
	 * the rumble time runs (0 after), the big one on while the high rumble time runs */
	CPad *pad = (u32)m_padid < 2 ? CInput::m_pads[m_padid] : NULL;

	if (pad == NULL)
		return;

	if (!(m_rumbletime <= 0.0f))
	{
		pad->m_ActData[1] = (u8)(s32)m_rumblestr;
		m_rumbletime -= dT;
	}
	else
	{
		m_rumblestr = 0.0f;
		pad->m_ActData[1] = (u8)(s32)m_rumblestr;
	}

	if (!(m_highrumbletime <= 0.0f))
	{
		pad->m_ActData[0] = 1;
		m_highrumbletime -= dT;
	}
	else
	{
		pad->m_ActData[0] = 0;
	}
}

/* @socom-skeleton stub GetThrottleFromSpeed__9CSealCtrlFfi */
float CSealCtrl::GetThrottleFromSpeed(float speed, int axis)
{
	/* 0x2840d0: the throttle that gives a speed (GetSpeedFromThrottle's inverse): forward (0)
	 * and strafe (1) over the seal's maximum motion times its move speed modifier, turn (2)
	 * over the character dynamics' maximum turn rate. ELF: another axis divides by an unset
	 * local (kept as 1 here). */
	CZSealBody* seal = static_cast<CZSealBody *>(m_entity);
	f32 max = 1.0f;
	f32 other;

	if (axis == 1)
	{
		seal->GetMaxXMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 0)
	{
		seal->GetMaxZMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 2)
	{
		max = theCharacterDynamics.m_turn_maxRate;
	}

	return speed / max;
}

/* @socom-skeleton stub GetSpeedFromThrottle__9CSealCtrlFfi */
float CSealCtrl::GetSpeedFromThrottle(float throttle, int axis)
{
	/* 0x284020: the speed a throttle gives: forward (0) and strafe (1) scale the seal's
	 * maximum motion (x its move speed modifier), turn (2) the character dynamics' maximum
	 * turn rate. ELF: another axis multiplies an unset local (kept as 0 here). */
	CZSealBody* seal = static_cast<CZSealBody *>(m_entity);
	f32 max = 0.0f;
	f32 other;

	if (axis == 1)
	{
		seal->GetMaxXMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 0)
	{
		seal->GetMaxZMotion(max, other);
		max *= seal->m_movespeedmod;
	}
	else if (axis == 2)
	{
		max = theCharacterDynamics.m_turn_maxRate;
	}

	return throttle * max;
}

/* @socom-skeleton stub PostMortemPreTick__9CSealCtrlFf */
void CSealCtrl::PostMortemPreTick(float dT)
{
	/* 0x283f20 (CZSealBody::PreTick while dead; ELF returns 1): the pad still drives the
	 * throttles (the death camera's rotate stick), right / left (rising, outside the
	 * weapon menu) ask to move the spectator camera on / back; single player: SELECT+X asks
	 * for a respawn (CZSealBody::PostMortemPreTick). ELF: the pad is not NULL-tested. */
	CZSealBody *seal = static_cast<CZSealBody *>(m_entity);
	CPad *pad = m_padid < 2 ? CInput::m_pads[m_padid] : NULL;
	ThrottlesPreTick(pad, dT);
	MENU_STATE menu = m_menustate;
	seal->m_advance_camera = pad->m_state[static_cast<u8>(PAD_BUTTON::PAD_RIGHT)] == KEY_RISING && menu != stateWeaponSel;
	seal->m_retreat_camera = pad->m_state[static_cast<u8>(PAD_BUTTON::PAD_LEFT)] == KEY_RISING && menu != stateWeaponSel;

	if (theNetwork.m_bNetwork)
	{
		theVoice.m_block_talk = true; /* 0x283fd0: a dead network player cannot talk */
	}
	else if (pad->GetTwoButtons(PAD_BUTTON::PAD_SELECT, PAD_BUTTON::PAD_CROSS))
	{
		seal->m_needs_respawn = true;
	}
}

/* @socom-skeleton stub UpdateAiVisMap__9CSealCtrlFv */
bool CSealCtrl::UpdateAiVisMap()
{
	/* 0x283e60 (CZSealBody::UpdateAiMapLoc on a new cell): the vis map follows the body's
	 * valid AI map location; 0 without a vis map */
	if (m_vismap == NULL)
		return false;

	CAiMapLoc loc = static_cast<CZSealBody *>(m_entity)->m_mapLocValid;
	return CAiVisMap::UpdateDynamicVisMap(m_vismap, loc);
}

/* @socom-skeleton stub SetViewRange__9CSealCtrlFf */
void CSealCtrl::SetViewRange(float range)
{
	/* 0x283e00: the view range (value and decay goal); zero or less: 0.95 of the camera's
	 * mid plane */
	if (!(range <= 0.0f))
	{
		m_visrange.m_value = range;
		m_visrange.m_goal = range;
		return;
	}

	zdb::CCamera* cam = zdb::CWorld::m_world->m_camera;

	if (cam != NULL)
	{
		m_visrange.m_value = 0.95f * cam->m_mid_plane;
		m_visrange.m_goal = m_visrange.m_value;
	}
}

/* @socom-skeleton stub PerturbAimVector__9CSealCtrlFP6CPnt3D */
void CSealCtrl::PerturbAimVector(CPnt3D *dir)
{
	/* 0x283c00 (HandleFireWeapon): the shot direction spread by the body's accuracy: its
	 * right and up axes scaled by the x / y factor plus the size factor times a signed square
	 * of a random -1..1 each */
	CAccuracy *accuracy = &static_cast<CZSealBody *>(m_entity)->m_accuracy;
	CPnt3D up;
	up.x = 0.0f;
	up.y = 1.0f;
	up.z = 0.0f;
	CPnt3D right;
	CPnt3D top;
	dir->Cross(&up, &right, false);
	right.Cross(dir, &top, false);
	f32 r = (f32)(rand() - 0x3fffffff) * 9.313226e-10f;
	r = r < 0.0f ? -(r * r) : r * r;
	right.Scale(accuracy->FactorX + accuracy->Factor * r, &right);
	r = (f32)(rand() - 0x3fffffff) * 9.313226e-10f;
	r = r < 0.0f ? -(r * r) : r * r;
	top.Scale(accuracy->FactorY + accuracy->Factor * r, &top);
	CPnt3D out;
	dir->Add(&right, &out);
	out.Add(&top, dir);
}

/* @socom-skeleton stub TickMPBomb__9CSealCtrlFf */
void CSealCtrl::TickMPBomb(float dT)
{
	/* 0x2838f0 (PostTick-side, network: the action button held on the MP bomb): while a bomb
	 * node is engaged, the dropped MP bomb's node (CPickup::m_mpbombnode) within 20 in front of
	 * the body (GetClosestNode, 1024 far) is the defusal node; the timer runs while the engaged
	 * node is that node or the reticle's action node. When it runs out: at the defusal node with
	 * the bomb placed (state 3) the defuse is attempted (bomb pickup timer 1) and the defusal
	 * node cleared; else at an MP bomb site the body may use (CanPerformAction, inlined) the bomb
	 * is placed unless already placed (the action runs, HandlePlacingExlosive(154, 1, 0.2)) and
	 * the timer is disengaged. The engaged node is cleared then. */
	if (m_mpbomb_node == NULL)
		return;

	CZSealBody *seal = static_cast<CZSealBody *>(m_entity);
	zdb::CNode *bomb = CPickup::m_mpbombnode;
	f32 d = -1.0f;

	if (bomb != NULL)
	{
		const f32 (*m)[4] = seal->m_node->m_matrix.m_matrix;
		CPnt3D dir;
		dir.x = -m[2][0];
		dir.y = -m[2][1];
		dir.z = -m[2][2];
		d = bomb->GetClosestNode((const CPnt3D *)&m[3][0], &dir, 1024.0f, 20.0f, 0.0f, -1.0f);
	}

	if (d == -1.0f)
		bomb = NULL;

	m_bomb_defusal_node = bomb;

	if (m_mpbomb_node == m_bomb_defusal_node && d != -1.0f)
		m_mpbomb_timer -= dT;

	CNodeAction *action = seal->GetReticuleAction(true);

	if (action != NULL && m_mpbomb_node == action->m_node)
		m_mpbomb_timer -= dT;

	if (!(m_mpbomb_timer < 0.0f))
		return;

	if (m_bomb_defusal_node != NULL)
	{
		if ((u8)CZBombState::m_BombStatus.CurrentBombState == 3)
		{
			m_bombpickuptimer = 1.0f;
			seal->AttemptBombDefuse();
			m_bomb_defusal_node = NULL;
		}
	}
	else if (action != NULL && CanPerformAction(action) && action->m_type == CNodeAction::ACT_MPBOMB)
	{
		if ((u8)CZBombState::m_BombStatus.CurrentBombState != 3)
		{
			action->ExecuteAction(seal, 0);
			seal->m_kit.HandlePlacingExlosive((EQUIP_ITEM)154, 1.0f, 0.2f);
		}

		m_mpbomb_bTimerEngaged = 0;
	}

	m_mpbomb_node = NULL;
}

/* @socom-skeleton stub InitMPBomb__9CSealCtrlFv */
void CSealCtrl::InitMPBomb()
{
	/* 0x283750 (the action button pressed, network): with a defusal node in front, it is the
	 * engaged node (5 s, timer engaged); else at an MP bomb site the body may use
	 * (CanPerformAction, inlined) the last reticle node is */
	CZSealBody *seal = static_cast<CZSealBody *>(m_entity);
	CNodeAction *action = seal->GetReticuleAction(true);

	if (m_bomb_defusal_node != NULL)
	{
		m_mpbomb_node = m_bomb_defusal_node;
		m_mpbomb_timer = 5.0f;
		m_mpbomb_bTimerEngaged = 1;
		return;
	}

	if (action == NULL)
		return;

	if (CanPerformAction(action) && action->m_type == CNodeAction::ACT_MPBOMB)
	{
		m_mpbomb_node = seal->m_last_reticule.m_node;
		m_mpbomb_timer = 5.0f;
		m_mpbomb_bTimerEngaged = 1;
	}
}

